import com.sun.net.httpserver.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Bounded wait handlers never occupy the API executor or hold room/session locks while sleeping. */
final class LongPollServer implements AutoCloseable {
 final GunnyServer server;final Set<String> waiting=ConcurrentHashMap.newKeySet();
 final ExecutorService pool=new ThreadPoolExecutor(0,32,30,TimeUnit.SECONDS,new SynchronousQueue<Runnable>(),new ThreadPoolExecutor.AbortPolicy());
 LongPollServer(GunnyServer s){server=s;}
 void handle(HttpExchange x)throws IOException{try{pool.execute(()->serve(x));}catch(RejectedExecutionException e){x.sendResponseHeaders(503,-1);x.close();}}
 long state(GunnyServer.Room r){synchronized(r){long h=Objects.hash(r.phase,r.departureVersion,r.chunks.size(),r.botVotes,r.settled,r.queued,r.requestedMap,r.map,r.seconds,r.closedSlots,r.title);for(int i=0;i<r.count;i++){var a=r.members[i];h=h*31+(a==null?0:a.id.hashCode()+a.profile.wornMask+a.profile.gender+a.profile.equipped)+(a!=null&&a.armed?1:0)+r.battleEmoteUntil[i]+r.emotes[i]+r.selectedBots[i];}if(r.battle!=null){var b=r.battle;h=h*31+b.turn*71L+b.countdown+(b.pendingNext?17:0)+(b.over?29:0);for(int i=0;i<b.unitCount;i++){var u=b.units[i];h=h*31+u.x*37L+u.y*71L+u.hp*97L+u.energy+u.angle+u.power;}}return h;}}
 void serve(HttpExchange x){String token=null;boolean owned=false;try{if(!x.getRequestMethod().equals("POST"))throw new IOException("POST required");String auth=x.getRequestHeaders().getFirst("Authorization");if(auth==null||!auth.startsWith("Bearer "))throw new SecurityException();token=auth.substring(7);var s=server.sessions.get(token);if(s==null||s.expiry<System.currentTimeMillis())throw new SecurityException();byte[] data=x.getRequestBody().readNBytes(33);if(data.length!=16)throw new IOException("Bad wait packet");DataInputStream in=new DataInputStream(new ByteArrayInputStream(data));if(in.readInt()!=GunnyServer.MAGIC)throw new IOException("Bad protocol");int room=in.readInt();long cursor=in.readLong();if(!waiting.add(token))throw new IOException("Already waiting");owned=true;long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(12),mark=0;while(true){if(server.closed||server.sessions.get(token)!=s||s.expiry<System.currentTimeMillis())throw new SecurityException();var r=server.rooms.get(room);if(s.room!=room||r==null)break;mark=state(r);if(mark!=cursor||System.nanoTime()>=end)break;Thread.sleep(40);}ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(b);out.writeLong(mark);byte[] response=b.toByteArray();x.getResponseHeaders().set("Cache-Control","no-store");x.getResponseHeaders().set("Content-Type","application/octet-stream");x.sendResponseHeaders(200,response.length);x.getResponseBody().write(response);}catch(Exception e){try{x.sendResponseHeaders(e instanceof SecurityException?401:503,-1);}catch(Exception ignored){}}finally{if(owned)waiting.remove(token);x.close();}}
 public void close(){pool.shutdownNow();}
}
